const GIT_COMMIT = /\bgit\s+commit\b/;
const MESSAGE_ARGUMENT_WITH_LITERAL_NEWLINE = /(?:^|\s)(?:-m|--message)(?:=|\s+)(?:"[^"]*\\n[^"]*"|'[^']*\\n[^']*'|[^\s;&|]*\\n[^\s;&|]*)/;

export default function commitMessageGuardExtension(pi: ExtensionAPI): void {
	pi.on("tool_call", (event) => {
